#include "array.h"
#include <stdint.h>  // SIZE_MAX
#include <string.h>  // memmove
#include "ctx.h"

#define ARRAY_MIN_CAPACITY 4

void* array_reserve_helper(Ctx* ctx,
                           void* data,
                           size_t* capacity,
                           size_t min_capacity,
                           size_t elem_size) {
  if (min_capacity <= *capacity) {
    return data;
  }
  if (elem_size == 0) {
    THROW(E_INTERNAL_ERROR, "Cannot grow array: element size is 0");
  }

  size_t max_capacity = SIZE_MAX / elem_size;
  if (min_capacity > max_capacity) {
    THROW(E_INTERNAL_ERROR, "Cannot grow array: capacity %zu overflows",
          min_capacity);
  }

  size_t new_capacity =
      *capacity < ARRAY_MIN_CAPACITY ? ARRAY_MIN_CAPACITY : *capacity;
  while (new_capacity < min_capacity) {
    new_capacity =
        new_capacity > max_capacity / 2 ? max_capacity : new_capacity * 2;
  }
  if (new_capacity > max_capacity) {
    new_capacity = max_capacity;
  }

  if (data == NULL) {
    data = TRY_MALLOC(new_capacity * elem_size);
  } else {
    TRY_REALLOC(data, new_capacity * elem_size);
  }
  *capacity = new_capacity;
  return data;
}

void* array_insert_helper(Ctx* ctx,
                          void* data,
                          size_t* count,
                          size_t* capacity,
                          size_t index,
                          size_t elem_size) {
  if (index > *count) {
    THROW(E_INTERNAL_ERROR,
          "Cannot insert into array: index %zu out of bounds (count %zu)",
          index, *count);
  }
  if (*count == SIZE_MAX) {
    THROW(E_INTERNAL_ERROR, "Cannot insert into array: count overflows");
  }

  data = array_reserve_helper(ctx, data, capacity, *count + 1, elem_size);
  char* bytes = data;
  memmove(bytes + (index + 1) * elem_size, bytes + index * elem_size,
          (*count - index) * elem_size);
  (*count)++;
  return data;
}

void array_remove_helper(Ctx* ctx,
                         void* data,
                         size_t* count,
                         size_t index,
                         size_t elem_size) {
  if (index >= *count) {
    THROW(E_INTERNAL_ERROR,
          "Cannot remove from array: index %zu out of bounds (count %zu)",
          index, *count);
  }

  char* bytes = data;
  memmove(bytes + index * elem_size, bytes + (index + 1) * elem_size,
          (*count - index - 1) * elem_size);
  (*count)--;
}
